import{_ as o,o as i,c as a,a2 as n}from"./chunks/framework.BN2sqjC1.js";const m=JSON.parse('{"title":"ADR-0024 — Parità funzionale con i plugin Excalidraw ed Excalidraw Extras di terze parti","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0024-excalidraw-feature-parity.md","filePath":"adr/0024-excalidraw-feature-parity.md"}'),t={name:"adr/0024-excalidraw-feature-parity.md"};function r(d,e,c,l,s,p){return i(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="adr-0024-—-parita-funzionale-con-i-plugin-excalidraw-ed-excalidraw-extras-di-terze-parti" tabindex="-1">ADR-0024 — Parità funzionale con i plugin Excalidraw ed Excalidraw Extras di terze parti <a class="header-anchor" href="#adr-0024-—-parita-funzionale-con-i-plugin-excalidraw-ed-excalidraw-extras-di-terze-parti" aria-label="Permalink to &quot;ADR-0024 — Parità funzionale con i plugin Excalidraw ed Excalidraw Extras di terze parti&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Stato</strong></td><td>accettata</td></tr><tr><td><strong>Recepito in</strong></td><td><code>Specifications.md</code> v1.4 (2026-11-02): §2.2.1, §2.4, §2.6.6, §2.7, §3.4.6, §4.2 (Appendice C.4)</td></tr><tr><td><strong>Data</strong></td><td>2026-10-27</td></tr><tr><td><strong>Riferimenti spec</strong></td><td>§2.7 (Excalidraw), §2.4 (indicizzazione), §3.4.5 (merge); V-02/D-01, V-08, D-04, D-06; ADR-0003, ADR-0005, ADR-0010, ADR-0021</td></tr><tr><td><strong>Devia dallo spec?</strong></td><td>sì, in modo puntuale: nuove funzioni di §2.7 (export, embed di parti, formule, azioni sulla scena), nuova dipendenza MathJax</td></tr></tbody></table><p><strong>Aggiornamento 2026-11-15.</strong> <a href="./0054-editor-dei-disegni-merge-undo-ricarica-libreria-ricerca.html">ADR-0054</a> (proposta) emenda la decisione 5: l&#39;auto-export non parte a ogni salvataggio ma 15 secondi dopo l&#39;ultimo, e subito alla chiusura del disegno, del vault o dell&#39;app.</p><p><strong>Aggiornamento 2026-11-02.</strong> Il sotto-flag citato in «Questioni aperte» come <code>drawing_scripts</code> è <code>drawing_actions</code> (decisione 26, schema del Config Profile); la dipendenza Excalidraw è il fork di ADR-0028.</p><h2 id="contesto" tabindex="-1">Contesto <a class="header-anchor" href="#contesto" aria-label="Permalink to &quot;Contesto&quot;">​</a></h2><p>Si portano nell&#39;editor dei disegni le funzioni dei plugin Excalidraw ed Excalidraw Extras di terze parti, senza cambiare l&#39;architettura (client Wails, Go solo dove serve) e mantenendo i file come <code>*.excalidraw</code> con JSON in chiaro (§2.7.1). Il plugin ha un motore di script utente (ExcalidrawAutomate) e dipendenze che richiedono rete, eval o accesso privilegiato: in conflitto con V-02/D-01 e con la CSP di ADR-0005.</p><h2 id="decisione" tabindex="-1">Decisione <a class="header-anchor" href="#decisione" aria-label="Permalink to &quot;Decisione&quot;">​</a></h2><ol><li><p><strong>Nessun motore di script.</strong> Le funzioni degli script della libreria diventano <strong>azioni native</strong> compilate (<code>drawing/actions/*</code>): funzioni pure dalla selezione a una patch (<code>ScenePatch</code>), esposte come comandi <code>drawing:&lt;id&gt;</code> (palette, hotkey, menu) e disattivabili col flag <code>drawings</code> del Config Profile. Una patch tocca solo <code>elements</code>/<code>files</code>, incrementa <code>version</code> e <code>versionNonce</code> degli elementi toccati e marca gli eliminati con <code>isDeleted</code> (mai rimossi): il merge per id (§3.4.5) non cambia.</p></li><li><p><strong>Formato.</strong> Nessun <code>.excalidraw.md</code> né LZ-string. I metadati aggiuntivi stanno in <code>customData.memobrain</code> dell&#39;elemento (es. <code>{kind:&quot;latex&quot;, latex, w0, color}</code>); il file resta JSON standard apribile con qualsiasi strumento.</p></li><li><p><strong>Impostazioni per vault</strong> in <code>.memobrain/drawing.json</code> (aggiunto all&#39;elenco ammesso di <code>bindings_meta.go</code>): modalità di apertura, posizione e nome dei nuovi disegni, larghezza dell&#39;embed, default e auto-export. Non passano (ancora) dal Config Profile, salvo il flag <code>drawings</code>.</p></li><li><p><strong>Embed di parti.</strong> <code>![[x.excalidraw#frame=Nome]]</code>, <code>#clippedframe=</code>, <code>#group=</code>, <code>#area=</code> (anche nella forma <code>#^frame=</code>): <code>drawing/embed/ref.ts</code>. L&#39;anteprima di una parte non usa la cache su disco (chiave = solo hash del file) ma solo la cache in memoria.</p></li><li><p><strong>Export.</strong></p><ul><li><code>ExportAPI.SaveFile(vaultID, nome, mime, base64)</code>: finestra di salvataggio nativa per PNG, SVG, PDF e JSON excalidraw. Valida firma e contenuto (l&#39;SVG passa dallo stesso controllo &quot;self-contained&quot; di <code>SaveHTML</code>), rifiuta destinazioni dentro il vault. Chiude il &quot;in futuro&quot; di ADR-0010 §4.</li><li><code>DrawingAPI.WriteExport(vaultID, disegno, variante, formato, base64)</code>: sovrascrive <code>X.excalidraw[.light|.dark].png|svg</code> accanto al disegno (stessa convenzione di nomi del plugin). Il percorso lo calcola Go; il frontend non sceglie dove scrivere.</li><li>Auto-export dopo ogni salvataggio seguito da una modifica; ambito: tutto, selezione o singolo frame; scena incorporabile (<code>exportEmbedScene</code>) per ricaricarla in Excalidraw.</li></ul></li><li><p><strong>Rinomina.</strong> <code>links.PlanRename</code> riscrive anche i <code>[[link]]</code> dentro i <code>.excalidraw</code> (campo <code>link</code> e testi), con modifica byte-per-byte del JSON grezzo (nessuna ri-serializzazione); salta le stringhe URL e i link che richiederebbero escape JSON. Chiude il limite noto di ADR-0010 §7 per i disegni (non per i canvas).</p></li><li><p><strong>Indicizzazione.</strong> <code>drawing.Parse</code> aggiunge i nomi dei frame al testo ricercabile.</p></li><li><p><strong>Formule LaTeX.</strong> Nuova dipendenza <strong><code>mathjax-full</code> 3.2.2</strong> (Apache-2.0, giugno 2022), solo lato frontend, caricata in lazy (chunk separati). Input TeX con i soli pacchetti <code>base, ams, newcommand, noundefined, boldsymbol, braket, cancel, color, mathtools, physics, textmacros</code> (registrati uno a uno, <strong>non</strong> <code>AllPackages</code>: niente <code>html</code>, <code>autoload</code>, <code>require</code>) e output SVG con glifi come tracciati (nessun font, nessuna rete). L&#39;SVG viene ripulito (<code>sanitizeSvg</code>): niente <code>&lt;a&gt;</code>, <code>class</code>, <code>style</code>, <code>data-*</code>, <code>href</code> esterni, <code>&lt;script&gt;</code>; il pacchetto base accetta comunque <code>\\href</code>, <code>\\class</code>, <code>\\style</code>, <code>\\cssId</code>, quindi la protezione è sull&#39;output, non sul parser. La formula è un elemento <code>image</code> con l&#39;SVG in <code>files</code>.</p></li><li><p><strong>Mermaid → Excalidraw.</strong> Dipendenza <strong><code>@excalidraw/mermaid-to-excalidraw</code> 1.1.2</strong> (MIT, novembre 2024), caricata in lazy solo dal dialogo &quot;Da testo a diagramma&quot;. I diagrammi di flusso, di sequenza e di classe diventano forme modificabili; gli altri tipi diventano un&#39;immagine SVG. La libreria porta la <strong>propria copia di <code>mermaid</code> 10.9.3</strong>, isolata da quella 12.x usata dal reading view (due istanze, nessuna configurazione condivisa). Si passa <code>securityLevel: &#39;strict&#39;</code> esplicitamente; gli elementi risultanti sono Excalidraw puro, raggruppati e centrati nella vista. Verificata con un test e2e in Chromium (inserimento, JSON salvato in chiaro, nessuna richiesta esterna): in jsdom non è eseguibile (<code>getBBox</code>).</p></li><li><p><strong>Azioni forme e frecce.</strong> Forme: riquadro e ellisse attorno alla selezione, riquadro per ogni gruppo, cambio di forma. Frecce: collegamento di forme in ordine di lettura (frecce legate a entrambi i lati, con <code>boundElements</code> aggiornati), connettori ad angolo retto, raddrizzamento, punto di piega, &quot;passo successivo di un processo&quot;. Gli elementi nuovi sono <em>skeleton</em> completati da <code>restoreElements(…, { refreshDimensions: true })</code> nell&#39;editor, che li rimisura con i font reali.</p></li><li><p><strong>Le frecce seguono le forme mosse dalle azioni.</strong> <code>PatchBuilder.moveTo</code> sposta l&#39;estremo legato di ogni freccia (non a gomito) insieme alla forma e lascia fermo l&#39;altro; le frecce non vengono mai disposte per conto proprio. Chiude il limite dichiarato in precedenza per lo spostamento (non per il ridimensionamento).</p></li><li><p><strong>Immagini e note dentro il disegno.</strong> Le immagini del vault (png, jpeg, gif, webp, svg, bmp, avif; max 8 MB) entrano in <code>files</code> come data URL (§2.7.1), con <code>customData.memobrain = {kind:&quot;image&quot;, path}</code>. Una <strong>nota</strong> entra come <em>scheda</em>: un rettangolo con il titolo e un estratto in testo semplice, <code>link: [[percorso/nota]]</code>. <strong>Deroga al piano</strong>, che prevedeva uno snapshot SVG: renderizzare il Markdown in <code>foreignObject</code> richiederebbe un CSS dedicato, i font e KaTeX incorporati, in tensione con D-01 e con la CSP (ADR-0005). La scheda resta JSON in chiaro, si apre con un clic, mostra l&#39;anteprima della nota al passaggio del mouse con Cmd/Ctrl (§2.2/ADR-0014), compare tra i backlink della nota (indice) e segue la rinomina (decisione 6). Non si aggiorna da sola quando la nota cambia.</p></li><li><p><strong>Tre difetti trovati scrivendo gli e2e e corretti.</strong> (a) La scala PNG dell&#39;export non veniva applicata dal M3: l&#39;API pubblica <code>exportToBlob</code> ignora <code>appState.exportScale</code> e usa <code>getDimensions</code>. (b) Con elementi selezionati Excalidraw consuma <code>Mod+P</code>/<code>Mod+O</code>: l&#39;editor ora gestisce in fase di cattura i soli comandi di navigazione (<code>palette:open</code>, <code>switcher:open</code>). (c) Un dialogo aperto da un comando della palette perdeva il focus perché la palette lo restituiva al canvas chiudendosi: <code>modalFocus</code> lo restituisce solo se non resta aperto nessun modale.</p></li><li><p><strong>Boolean Operations con <code>polygon-clipping</code> 0.15.7</strong> (MIT, dicembre 2023, tipi inclusi, due dipendenze piccole; <code>yarn npm audit</code> pulito). Rettangoli, rombi, ellissi (72 lati) e linee chiuse diventano anelli; unione, intersezione, differenza (la forma più in basso meno le altre) e xor producono linee chiuse con lo stile della forma più in basso, e le originali sono marcate <code>isDeleted</code>. Un buco diventa un anello unico con un&#39;asola a larghezza zero (&quot;keyhole&quot;), perché un contorno non ha buchi. Lo stesso motore dà <em>Split Ellipse</em>. Il modulo è importato staticamente dalle azioni (≈ 30 kB).</p></li><li><p><strong>Azioni di testo, di vista e utilità.</strong> Dividi il testo per righe, unisci i testi, note adesive, testo→link, ripeti elementi, freedraw→linea (Ramer–Douglas–Peucker), <em>Auto Layout</em> a livelli (cammino più lungo, cicli spezzati sull&#39;arco che li chiude, frecce che seguono). Le azioni di &quot;vista&quot; (zoom sulla selezione, griglia, selezione per tipo, copia stile nei predefiniti) restituiscono un <code>view</code> della patch e non toccano il disegno.</p></li><li><p><strong>Impostazioni nel file stesso.</strong> Le impostazioni <em>per disegno</em> (oggi: l&#39;auto-export) stanno nella chiave di primo livello <code>memobrain</code> del JSON: Excalidraw la ignora, <code>parseScene</code> la conserva (<code>extra</code>) e ogni salvataggio la riscrive. Il merge (§3.4.5) segue per queste chiavi il lato che ha cambiato.</p></li><li><p><strong>PDF.</strong> &quot;Stampa / PDF…&quot; mette l&#39;SVG del disegno sul livello di stampa dell&#39;app (<code>beginPrint</code>, come l&#39;export delle note) e apre la finestra di stampa di sistema, da cui si salva in PDF.</p></li><li><p><strong>Immagini, note e disegni dal vault.</strong> Si inseriscono da comando e con il drag&amp;drop dall&#39;explorer (tipo MIME <code>application/x-memobrain-path</code>). Un altro disegno entra come SVG in <code>files</code> (<code>customData.memobrain.kind = &quot;drawing&quot;</code>); un disegno non si inserisce in se stesso. Le schede-nota si aggiornano con &quot;Aggiorna le schede&quot;, che rilegge il testo (la scheda conserva forma e colori). &quot;Crea una nuova nota e aggiungi la scheda&quot; e &quot;Sposta la selezione in un nuovo disegno&quot; scrivono i file del vault; il secondo salva l&#39;originale prima di cambiare tab (<code>controller.save()</code>).</p></li><li><p><strong>Embed e stili predefiniti.</strong> Gli embed accettano le parole chiave di allineamento del plugin (<code>|left</code>, <code>|right</code>, <code>|center</code>, <code>|left-wrap</code>, <code>|right-wrap</code>, insieme alla dimensione) con classi interne dell&#39;app. Per vault si possono fissare colore del tratto, riempimento, carattere e dimensione dei nuovi elementi.</p></li><li><p><strong>Testi aggiornati da una patch</strong> sono rimisurati con i font reali (e il loro contenitore ridimensionato): cambiare carattere o rileggere una scheda non lascia più misure vecchie.</p></li><li><p><strong>Generatori e schemi.</strong> Mindmap Builder (un testo-elenco indentato diventa un albero di riquadri con frecce legate, il testo sorgente viene sostituito), calendari annuale e lineare, vignette e nuvolette, Color Scheme Manager (ogni colore distinto della selezione è sostituito dal successivo dello schema, mantenendo le relazioni) e Organic Line (linea → tratto freedraw rastremato). I generatori si posizionano al centro dello schermo (<code>SceneContext.origin</code>).</p></li><li><p><strong>Frecce legate al ridimensionamento.</strong> <code>PatchBuilder.setBox</code> rimette gli estremi legati sul bordo della forma ridimensionata, sulla retta verso l&#39;altro estremo (lo spostamento era già gestito).</p></li><li><p><strong>Presentazione a diapositive.</strong> Ogni <code>frame</code> è una diapositiva; l&#39;ordine è <code>customData.memobrain.slide</code> se presente, altrimenti il nome in ordine &quot;naturale&quot;, altrimenti la posizione. Frecce/Pagina/Spazio/Home/Fine navigano, Esc esce; con il puntatore laser come strumento. Senza cornici la presentazione resta quella di prima. Il tasto che avvia il comando (Invio nella palette) non fa avanzare la prima diapositiva.</p></li><li><p><strong>Penne e pannello Strumenti.</strong> Penna fine, pennarello, evidenziatore e puntatore laser sono comandi (assegnabili a una scorciatoia); il pannello &quot;Strumenti&quot; elenca tutte le azioni con ricerca, preferiti (<code>toolFavorites</code> in <code>.memobrain/drawing.json</code>, sincronizzati) e usati di recente (per dispositivo, <code>localStorage</code>).</p></li><li><p><strong>Import.</strong> <code>DrawingAPI.ImportLegacy</code> converte un <code>.excalidraw.md</code> del plugin (dati <code>compressed-json</code> LZ-string o <code>json</code>) in un <code>.excalidraw</code> in chiaro accanto all&#39;originale, che resta intatto; le immagini di &quot;Embedded Files&quot; sono lette dal vault (anche per solo nome) e inserite come data URL. La decompressione LZ-string è in Go (<code>internal/drawing/legacy.go</code>), verificata con un vettore generato da <code>lz-string</code> 1.5.0. Le librerie <code>.excalidrawlib</code> si importano con <code>loadLibraryFromBlob</code> di Excalidraw e si esportano copiando la libreria del vault in <code>Library.excalidrawlib</code>.</p></li><li><p><strong>Sotto-flag del profilo di configurazione.</strong> <code>drawing_latex</code>, <code>drawing_mermaid</code>, <code>drawing_auto_export</code> e <code>drawing_actions</code> (in <code>features.go</code> e nello schema del profilo) nascondono ciascuno una famiglia di funzioni; non hanno effetto se <code>drawings</code> è spento e sono accesi di default.</p></li><li><p><strong>Note del relatore e descrizione testuale.</strong> Le note stanno in <code>customData.memobrain.notes</code> della cornice e compaiono sotto la diapositiva; «Descrivi il disegno come testo» è un dialogo con contenuto, cornici, testi e link, per l&#39;accessibilità.</p></li><li><p><strong>Soglia immagini</strong> 10 MB per file inserito (come la soglia per disegno di §2.7.1); lato Go <code>drawing.Parse</code> segnala (<code>Warnings</code>, log dell&#39;indicizzatore) le voci di <code>files</code> oltre la soglia senza bloccare il salvataggio. <strong>Lingue:</strong> <code>drawing/lang.ts</code> mappa la lingua dell&#39;app su quelle di Excalidraw (<code>languages</code>), con ripiego <code>en</code>. <strong>Formule di <code>.excalidraw.md</code>:</strong> <code>ConvertLegacyMD</code> marca le immagini con <code>customData.memobrain</code> (<code>kind: latex</code>) e l&#39;editor le disegna all&#39;apertura con MathJax.</p></li><li><p><strong>Verifica.</strong> Fixture di conformance del merge per cornici/<code>customData</code>, immagini aggiunte da entrambi i lati e chiave <code>memobrain</code>; test di sync a due dispositivi con elementi extra, esportazioni derivate e <code>drawing.json</code>; scansione axe del chrome dei disegni.</p></li></ol><h2 id="alternative-considerate" tabindex="-1">Alternative considerate <a class="header-anchor" href="#alternative-considerate" aria-label="Permalink to &quot;Alternative considerate&quot;">​</a></h2><ul><li><strong>Motore di script in worker isolato.</strong> Scartato: richiede di modificare V-02/D-01 e di mantenere un&#39;API di scripting; le azioni native coprono gli script della libreria senza codice utente.</li><li><strong>KaTeX per le formule.</strong> Scartato: produce HTML/MathML, non SVG; servirebbe misurare il DOM per ottenere un&#39;immagine.</li><li><strong>Salvare il <code>.excalidraw.md</code> del plugin.</strong> Scartato: contraddice §2.7.1 e la richiesta di JSON in chiaro.</li></ul><h2 id="conseguenze" tabindex="-1">Conseguenze <a class="header-anchor" href="#conseguenze" aria-label="Permalink to &quot;Conseguenze&quot;">​</a></h2><ul><li>Il bundle cresce solo con chunk lazy (MathJax SVG ≈ 1,2 MB, ≈ 490 kB gzip): non pesa su avvio e apertura note (ADR-0020), ma va verificato nel budget di rilascio.</li><li><code>yarn.lock</code> guadagna 8 pacchetti per <code>mathjax-full</code> (~41 MB su disco) e 38 per il convertitore Mermaid (~26 MB, tra cui <code>mermaid</code> 10.9.3). Dopo l&#39;installazione <code>yarn npm audit --severity high</code> non segnala nulla: il gate resta bloccante (ADR-0021); rivedere le <code>resolutions</code> a ogni aggiornamento.</li><li>Limiti noti: i buchi delle Boolean Operations lasciano una sottile asola visibile con il tratto; le schede-nota si aggiornano solo su richiesta; la conversione di <code>.excalidraw.md</code> non porta il testo fuori da <code>## Drawing</code>; non sono implementati: Icon Library (servono asset che non abbiamo offline), Image Occlusion, LayerManager, Crop Vintage Mask, Collaboration Frame (D-04), Hardware Eraser (richiede una penna; Scribble Helper e gli strumenti lazo/secchiello/disegna per la forma arrivano con il fork, ADR-0028), Capture Note, Folder Note, &quot;Fixed inner distance&quot; (comportamento non documentato nelle fonti consultate); la modalità per mancini non esiste in Excalidraw 0.18 (da riverificare nel fork).</li><li>Copertura: gli e2e Playwright (<code>e2e/drawing-*.spec.ts</code>) girano su Chromium con i binding simulati; la checklist manuale sul webview reale (<code>docs/qa/m3-drawings-canvas.md</code>) va estesa a queste funzioni.</li></ul><h2 id="questioni-aperte" tabindex="-1">Questioni aperte <a class="header-anchor" href="#questioni-aperte" aria-label="Permalink to &quot;Questioni aperte&quot;">​</a></h2><ul><li><strong>Aggiornamento di Mermaid → Excalidraw.</strong> <code>@excalidraw/mermaid-to-excalidraw@3.0.0</code> (pubblicata il 2026-10-27, dipende da <code>pele@1.8.0</code> del 2026-10-20) non è stata adottata per la sua età. Rivalutare dopo che le versioni 3.x hanno almeno due settimane e un audit del pacchetto <code>pele</code>; così si eliminerebbe anche la seconda copia di <code>mermaid</code>.</li><li>Aggiornare <code>Specifications.md</code> (a cura dell&#39;owner): §2.7 (esportazione e auto-export, embed di parti con <code>#frame=</code>/<code>|left</code>, formule LaTeX, Mermaid, azioni sulla scena, presentazione, <code>.memobrain/drawing.json</code>, import di <code>.excalidraw.md</code>/<code>.excalidrawlib</code>); §2.4 (i nomi delle cornici sono indicizzati); matrice funzioni (<code>drawing</code> rispetto al flag <code>drawings</code> e i sotto-flag <code>drawing_latex</code>, <code>drawing_mermaid</code>, <code>drawing_auto_export</code>, <code>drawing_scripts</code>); riferimenti a Vite (ADR-0025: esbuild per desktop e web, Vite resta solo come dipendenza di Vitest).</li></ul>',14)])])}const u=o(t,[["render",r]]);export{m as __pageData,u as default};
